def main():
    out = Path(__file__).resolve().parent.parent / "source_catalog.csv"
    for r in ROWS:
        assert len(r) == len(COLS), (r[0], len(r), len(COLS))
    assert len({r[0] for r in ROWS}) == len(ROWS)
    with open(out, "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, quoting=csv.QUOTE_ALL)
        w.writerow(COLS)
        w.writerows(ROWS)
    import collections
    c = collections.Counter(r[COLS.index("trang_thai_kiem_chung")] for r in ROWS)
    print(len(ROWS), "nguồn;", dict(c))


if __name__ == "__main__":
    main()
